public class MetaspaceExploration {
    public static void main(String[] args) throws Exception {
        // Demonstrating dynamic class generation which populates Metaspace
        int i = 0;
        while (true) {
            ClassLoader cl = new ClassLoader() {
                @Override
                public Class<?> loadClass(String name) throws ClassNotFoundException {
                    return super.loadClass(name);
                }
            };
            // Each unique ClassLoader instance holding distinct class metadata 
            // will allocate space in Metaspace until class unloading occurs.
            if (i++ % 10000 == 0) {
                System.out.println("Loaded batches of classes. Current Metaspace pressure monitored via JMX.");
            }
        }
    }
}
